alter table public.traveling_tokens add column if not exists activation_pin_last4 text; alter table public.traveling_tokens add column if not exists pin_generated_at timestamptz; alter table public.traveling_tokens add column if not exists pin_consumed_at timestamptz; alter table public.traveling_tokens add column if not exists provisioned_at timestamptz;
create sequence if not exists public.traveling_token_serial_seq start 1;
create or replace function public.admin_provision_traveling_token() returns table(traveling_token_id uuid,token_code text,activation_pin text,nfc_public_token uuid,nfc_path text) language plpgsql security definer set search_path='' as $$ declare v_id uuid; v_code text; v_pin text; v_nfc uuid; begin if not public.is_legacy_link_admin() then raise exception 'Admin access required'; end if; v_code:='LL-TT-'||lpad(nextval('public.traveling_token_serial_seq')::text,6,'0'); v_pin:=upper(substr(replace(gen_random_uuid()::text,'-',''),1,6)); v_nfc:=gen_random_uuid(); insert into public.traveling_tokens(token_code,nfc_public_token,activation_pin_hash,activation_pin_last4,pin_generated_at,provisioned_at,status) values(v_code,v_nfc,crypt(v_pin,gen_salt('bf')),right(v_pin,4),now(),now(),'unclaimed') returning id into v_id; return query select v_id,v_code,v_pin,v_nfc,'/t/'||v_nfc::text; end; $$;
create or replace function public.get_traveling_token_activation_state(p_nfc_public_token uuid) returns table(token_id uuid,token_code text,status text,is_owner boolean) language sql stable security definer set search_path='' as $$ select t.id,t.token_code,t.status,(t.owner_id=auth.uid()) from public.traveling_tokens t where t.nfc_public_token=p_nfc_public_token limit 1; $$;
create or replace function public.claim_traveling_token(p_nfc_public_token uuid,p_activation_pin text) returns table(token_id uuid,token_code text,status text) language plpgsql security definer set search_path='' as $$ declare v public.traveling_tokens%rowtype; begin if auth.uid() is null then raise exception 'Authentication required'; end if; select * into v from public.traveling_tokens where nfc_public_token=p_nfc_public_token for update; if v.id is null then raise exception 'Traveling Token not found'; end if; if v.status<>'unclaimed' then raise exception 'This Traveling Token has already been claimed'; end if; if v.activation_pin_hash is null or crypt(upper(trim(p_activation_pin)),v.activation_pin_hash)<>v.activation_pin_hash then raise exception 'Activation PIN does not match this Traveling Token'; end if; update public.traveling_tokens set owner_id=auth.uid(),creator_id=auth.uid(),status='draft',activated_at=now(),pin_consumed_at=now(),updated_at=now() where id=v.id; return query select v.id,v.token_code,'draft'::text; end; $$;
revoke all on function public.admin_provision_traveling_token() from public; grant execute on function public.admin_provision_traveling_token() to authenticated; revoke all on function public.get_traveling_token_activation_state(uuid) from public; grant execute on function public.get_traveling_token_activation_state(uuid) to anon,authenticated; revoke all on function public.claim_traveling_token(uuid,text) from public; grant execute on function public.claim_traveling_token(uuid,text) to authenticated;